import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788345439000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>WIKIJS_URL</code></td><td>yes</td><td>—</td><td>Base URL of the Wiki.js instance, e.g. <code>https://wiki.example.com</code>. A trailing <code>/graphql</code> is trimmed</td></tr><tr><td><code>WIKIJS_TOKEN</code></td><td>yes</td><td>—</td><td>API key from Administration → API Access. <code>WIKIJS_API_KEY</code> is accepted as an alias</td></tr><tr><td><code>WIKIJS_LOCALE</code></td><td>no</td><td><code>en</code></td><td>Locale assumed by page tools that are not given one</td></tr><tr><td><code>WIKIJS_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code>, <code>1</code> or <code>yes</code> registers only the read tools</td></tr><tr><td><code>WIKIJS_ALLOWED_PATHS</code></td><td>no</td><td>—</td><td>Page path prefixes the write tools are confined to, e.g. <code>docs,team/notes</code></td></tr><tr><td><code>WIKIJS_ALLOW_TOOLS</code></td><td>no</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>WIKIJS_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left</td></tr><tr><td><code>WIKIJS_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td>Exactly <code>true</code> accepts self-signed certificates</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><h2 id="wikijs-locale" tabindex="-1"><code>WIKIJS_LOCALE</code> <a class="header-anchor" href="#wikijs-locale" aria-label="Permalink to “WIKIJS_LOCALE”">​</a></h2><p>The locale is part of a page&#39;s identity in Wiki.js, not a display preference: <code>docs/setup</code> under <code>en</code> and under <code>de</code> are two different pages. Every tool that takes a <code>locale</code> falls back to this value, so a wiki set up in another language needs it — otherwise every lookup by path answers &quot;not found&quot; on a wiki that plainly has the page. <code>list_locales</code> reports what is installed.</p><h2 id="wikijs-allowed-paths" tabindex="-1"><code>WIKIJS_ALLOWED_PATHS</code> <a class="header-anchor" href="#wikijs-allowed-paths" aria-label="Permalink to “WIKIJS_ALLOWED_PATHS”">​</a></h2><p>Comma-separated page path prefixes. The <strong>writing</strong> page and asset tools refuse a target outside them; reads are unaffected.</p><p>Matching is by path segment: <code>docs</code> covers <code>docs</code> itself and anything under <code>docs/</code>, and does <strong>not</strong> cover <code>docs-archive</code>. <code>move_page</code> checks its source and its destination, so a page can be moved neither out of the allowed area nor into a protected one.</p><p>An empty or whitespace-only value counts as unset, the same as the tool lists. A prefix containing <code>..</code> or a wildcard aborts startup.</p><p>Three kinds of write it cannot confine, and refuses instead of pretending:</p><ul><li>The instance-wide maintenance tools act on every page there is: <code>purge_page_history</code>, <code>migrate_pages_locale</code>, <code>flush_page_cache</code>, <code>rebuild_page_tree</code> and <code>rebuild_search_index</code>. The last three lose nothing — they cost time — but &quot;every page in the wiki&quot; is outside any prefix all the same, so they are refused too.</li><li><code>update_tag</code> and <code>delete_tag</code> affect every page carrying the tag, wherever it lives.</li><li><code>update_comment</code> and <code>delete_comment</code> — Wiki.js does not report which page a comment belongs to, so there is no way to tell whether it is inside the allowed area. <code>create_comment</code> is given the page and is checked normally.</li></ul><p>Each of those refuses with a message naming the variable. Unset it to run them. <code>render_page</code> writes a single page and is checked against the prefix like any other page write — it changes no content, but it rewrites the stored HTML and bumps <code>updatedAt</code>, which is the field <code>update_page</code> reads to detect a concurrent edit.</p><p>Asset writes are checked against the <strong>asset folder</strong> path, which is a separate namespace from page paths: with <code>WIKIJS_ALLOWED_PATHS=docs</code>, uploads go into the asset folder <code>docs</code> or below, and the root is refused.</p><p>This is a second line, not the first one: the API key&#39;s own group and page rules in Wiki.js are what actually hide pages, from this server and the web UI alike.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><p><code>WIKIJS_ALLOW_TOOLS</code> and <code>WIKIJS_DENY_TOOLS</code> are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Registers</th></tr></thead><tbody><tr><td><code>essential</code></td><td>the curated preset, marked in the <a href="/reference/tools">tool reference</a></td></tr><tr><td><code>get_page,search_pages,list_*</code></td><td>exactly those</td></tr><tr><td><code>list_*</code></td><td>every tool whose name starts with <code>list_</code></td></tr><tr><td><code>*</code></td><td>everything — the same as leaving it unset</td></tr></tbody></table><p>Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>WIKIJS_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_thing</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>WIKIJS_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where the <code>WIKIJS_*</code> booleans fail <em>off</em> on a typo, this one stops the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em> <code>WIKIJS_TOKEN</code> and <code>WIKIJS_API_KEY</code> are deleted from <code>process.env</code>, so the fatal path cannot leave a credential sitting there for a crash reporter.</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};